import re
from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone, CommandFailure


class Epmd(GenericUnixCommand):
    """Unix erlang command empd."""

    def __init__(self, connection=None, options='', platform='rtg', prompt=None, newline_chars=None, runner=None):
        """
        Represents erlang command epmd.
        :param connection: moler connection to device, terminal where command is executed
        :param options: epmd command options as string
        :param prompt: prompt (on system where command runs).
        :param newline_chars: characters to split lines
        :param runner: Runner to run command
        """
        super(Epmd, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.current_ret = []
        self.options = options
        self.platform = platform
        self.ret_required = False

    def on_new_line(self, line, is_full_line):
        """
        Parses output from command.
        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._is_connection_error(line=line)
                self._is_epmd_running(line=line)
                self._parse_names(line=line)
            except ParsingDone:
                pass
        return super(Epmd, self).on_new_line(line, is_full_line)

    def _is_epmd_running(self, line):
        """
        Parse first line from output.
        :param line: Line from connection.
        :return: None
        """
        if "epmd: up and running on port" in line:
            raise ParsingDone

    def _is_connection_error(self, line):
        """
        Check for epmd connection error.
        :param line: Line from connection.
        :return: None
        """
        if "Cannot connect to local epmd" in line:
            raise CommandFailure(self, message="Cannot connect to local epmd")

    _re_name = re.compile(r"name\s(?P<APP>.+)\sat\sport\s(?P<PORT>\d+)")

    def _parse_names(self, line):
        """
        Parse name list from output.
        :param line: Line from connection.
        :return: None
        """
        if self._regex_helper.search(self._re_name, line):
            app = self._regex_helper.group('APP')
            port = self._regex_helper.group('PORT')
            empn_names = {'APP': app, 'PORT': port}
            self.current_ret.append(empn_names)
            raise ParsingDone

    def build_command_string(self):
        """
        Builds string with command.
        :return: String with command.
        """
        cmd = "/opt/{}/lib/erlang/bin/epmd".format(self.platform)
        if self.options:
            cmd = "{} {}".format(cmd, self.options)
        return cmd
